(function(root){
const types=['assets','alerts','incidents','vendors','brand','credentials','executives','rules','requests','feeds','reports','history'];
const record=(id,title,asset,severity='High',status='Open',type='Domain')=>({id,title,asset,severity,status,type,date:'2026-09-13',notes:'Sample finding for demonstration purposes.'});
function seed(){const s={organization:{name:'Demo Corp',domain:'democorp.com',industry:'Financial Services'},score:40};types.forEach(t=>s[t]=[]);let domains=['democorp.com','democorp.io','api.democorp.com','login.democorp.com','vpn.democorp.com','mail.democorp.com','portal.democorp.com','democorp-cloud.com','democorp-pay.com','nexronix.io'];s.assets=domains.map((d,i)=>record('asset-'+i,d,d,i%3?'Medium':'High','Monitoring',i<2||i>6?'Domain':'Subdomain'));s.alerts=['Exposed credentials found in breach database','Security headers grade F','Active look-alike domain detected','Non-standard ports open','Critical software vulnerability','SSL certificate changed','New subdomain discovered','Supply chain vendor rated D','Leaked secret in repository','Email DMARC policy missing'].map((t,i)=>record('alert-'+i,t,domains[i],i===0||i===4?'Critical':i%3?'High':'Medium'));s.incidents=domains.slice(0,5).map((d,i)=>record('incident-'+i,'Mixed findings on '+d,d,i<2?'Critical':'High',i===3?'Investigating':'Open','Correlated incident'));s.vendors=['nexronix.io','cloudvendor.example','payments.example'].map((d,i)=>({...record('vendor-'+i,d,d,i===0?'High':'Low','Monitoring','Vendor'),grade:['D','B','A'][i]}));s.brand=['democ0rp-login.com','democorp-help.top','democorpsupport.io','democorpp.com','dimocorp.com','dermocorp.com'].map((d,i)=>record('brand-'+i,d,d,'High',i<3?'Needs review':i===3?'Resolved':'In takedown','Domain'));s.credentials=Array.from({length:8},(_,i)=>record('cred-'+i,'customer'+(i+1)+'@democorp.example','democorp.com',i<2?'Critical':'High','Open',i%2?'Breach':'Stealer log'));s.executives=[record('exec-0','Alex Morgan','alex.morgan@example.com','Medium','Monitoring','CEO')];s.feeds=['Sample ransomware campaign','New vulnerability advisory','Demo credential collection','Brand impersonation campaign','Initial access listing'].map((t,i)=>record('feed-'+i,t,'example.com','High','Published',['Ransomware','Vulnerabilities','Breaches','Threat Intel','Initial Access Brokers'][i]));s.history=domains.slice(0,5).map((d,i)=>record('history-'+i,d,d,'Low','Cached','Domain'));return s;}
function validate(input){if(!input||typeof input!=='object'||Array.isArray(input))throw Error('Expected a JSON object.');const next=seed();for(const t of types){if(input[t]!==undefined){if(!Array.isArray(input[t])||input[t].length>1000)throw Error(t+' must be an array with at most 1,000 records.');next[t]=input[t].map((r,i)=>{if(!r||typeof r!=='object'||typeof r.title!=='string'||!r.title.trim())throw Error(t+' record '+(i+1)+' needs a title.');const v=record(t+'-'+i,r.title.slice(0,300),String(r.asset||'example.com').slice(0,300));for(const k of ['severity','status','type','notes','date','grade'])if(typeof r[k]==='string')v[k]=r[k].slice(0,2000);return v})}}if(input.organization){for(const k of ['name','domain','industry'])if(typeof input.organization[k]==='string')next.organization[k]=input.organization[k].slice(0,160)}if(input.score!==undefined){if(!Number.isFinite(input.score)||input.score<0||input.score>100)throw Error('Score must be between 0 and 100.');next.score=input.score}return next}
const api={types,record,seed,validate};if(typeof module!=='undefined')module.exports=api;else root.DemoData=api;
})(typeof window==='undefined'?globalThis:window);
